import{_ as n,a0 as u,w as s,s as a,ao as l,I as i,x as t,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"戴文的Linux內核專題：18 配置內核 (14) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：18 配置內核 (14) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：18 配置內核 (14) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：18 配置內核 (14) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/18 The Linux Kernel--Configuring the Kernel Part 14","title":"戴文的Linux內核專題：18 配置內核 (14)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/18 The Linux Kernel--Configuring the Kernel Part 14.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/18 The Linux Kernel--Configuring the Kernel Part 14.md"};function I(q,e,L,S,P,c){const p=u("Link");return s(),a("div",null,[e[11]||(e[11]=l('<h1 id="戴文的linux內核專題-18-配置內核-14" tabindex="-1">戴文的Linux內核專題：18 配置內核 (14) <a class="header-anchor" href="#戴文的linux內核專題-18-配置內核-14" aria-label="Permalink to “戴文的Linux內核專題：18 配置內核 (14)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.566/" alt=""></p><p>你好！ 準備好讀另一篇很酷的Linux內核文章了麼?</p><p>接下來，在這個任務中，我們可以啓用/禁用&quot;Fusion MPT logging facility&quot;。MPT代表&quot;Message Passing Technology&quot;(消息傳遞技術)。Fusion驅動是由LSI Logic公司開發。MPT一種進程間使用的特定消息策略。這個技術是同步的意味着進程將會等待所需的消息。</p><p>在這之後，如果計算機處理擁有火線端口就應該啓用&quot;FireWire driver stack&quot;。如果沒有，那麼就沒有必要去啓動一個不會使用到的火線驅動。火線很像USB。不過在協議、速度、物理形狀和端口布局上不同。通常上，蘋果設備使用火線和USB。一些PC有火線端口，但是不像USB口那樣普及。</p><p>一些火線控制器使用OHCI-1394規範(OHCI-1394 controllers)。如果是這樣，啓用這個驅動。</p><p>為了使用火線存儲設備，啓用下一個驅動(Storage devices (SBP-2 protocol))。這個驅動提供了火線存儲單元與火線總線通信的協議(the card with the attached FireWire ports)。一些火線掃描儀同樣需要這個驅動。</p><p>IPv4可以用在火線端口(IP networking over 1394)。IEEE 1394或者簡單的&quot;1394&quot;就是火線。使用IPv4在火線多播有侷限。</p><p>&quot;Nosy&quot;是&quot;FireWire PCILynx&quot;卡上的流量監控(Nosy - a FireWire traffic sniffer for PCILynx cards)。</p><p>下一步，可以支持I2O設備(I2O device support)。&quot;Intelligent Input/Output (I2O)&quot;(智能輸入/輸出)總線使用硬件和操作系統層的驅動。硬件驅動(hardware drivers (HDM))並不特定與任何操作系統而OS驅動(OS drivers (OSM))必須在目標操作系統上使用。OSM可以與任何HDM通信。I2O卡/總線有一個IOP- 輸入/輸出處理器(Input/Output Processor)。由於主CPU處理更少的數據，所以加速了系統。</p><p>只在缺乏SUN I2O控制器的系統上啓用&quot;Enable LCT notification&quot;。I2C SUN固件不支持LCT通知。 如果目標是RAID，Adaptec I2O控制器需要下一個驅動(Enable Adaptec extensions)。</p><p>64位的直接內存訪問可以在Adaptec I2O控制器上啓用(Enable 64-bit DMA)。</p><p>如果允許，可以配置I2O設備(I2O Configuration support)。這個特性主要用在RAID設定中。</p><p>可以為I2O啓用支持老的輸入/輸出控制(Enable ioctls (OBSOLETE))。</p><p>可以啓用I2O總線適配器的OSM軟件(I2O Bus Adapter OSM)。這組OSM被用來尋找新的在其他適配器末端的I2O設備。</p><p>下面，可以啓用I2O塊設備上的OSM(I2O Block OSM)。I2O硬件上的RAID控制器需要這個OSM。</p><p>下面的OSM用於I2O控制器上的SCSI或者光纖通道設備。</p><p>如果啓用了(I2O /proc support)，可以通過/proc讀取I2O設備的信息。</p><p>在啓用/禁用了I2O特性，我們可以繼續其他的內核特性。下面，我們看到&quot;Macintosh device drivers&quot;。這隻對蘋果設備有用。PC的Linux內核不應該有任何這些驅動啓用。然而，正如許多説法都有例外一樣。一些PC用户可能會使用蘋果鼠標、鍵盤和/或者一些其他的蘋果設備。再説一次，最好徹底地理解需求和正在開發的內核。</p><p>下一步，我們有一個用於網絡的驅動(Network device support)。X11和其他的Linux軟件不依賴於這個驅動，所以如果內核不會連接到另一台計算機、因特網、內聯網或者網絡，那麼這個特性可以安全地禁用。</p><p>下面的驅動就像上面，但是特定於核心驅動(Network core driver support)。</p><p>這個驅動支持Etherchannel(Bonding driver support)。&quot;bonding&quot;是兩條或者更多的以太網通道的融合。這也成為中繼。</p><p>使用這個驅動(Dummy net driver support)，可以在Linux中設置一個虛擬網絡。虛擬網絡(dummy network)就像網絡中的/dev/null。任何發送給虛擬網絡的數據都會永久消失，因為它會發往/dev/null。IP地址沒有設置。用户可以定義他們的網絡相當於/dev/null。</p><p>下一步，可以支持和EQL(EQL (serial line load balancing) support)。這允許兩台計算機使用SLIP或者PPP協議在兩條串行連接上通信。</p><p>光纖通道是一種用於連接存儲設備到計算機的快速串行協議(Fibre Channel driver support)。</p><p>TMII收發器需要這個驅動(Generic Media Independent Interface device support)。MII是一種用於最高速度為100Mbit/s以太網的接口。以太網線纜用於連接到PHYceiver，這是一種以太網收發器。</p><p>為了通過虛擬接口組織許多以太網設備，需要&quot;Ethernet team driver support&quot;。</p><p>&quot;MAC-VLAN support&quot;允許用户在特定的MAC地址和某個接口上映射數據包。</p><p>TAP字符設備可以由MAC-VLAN接口生成(MAC-VLAN based tap driver)。TAP設備從內核中獲取數據包，這樣它們就可以被送往其他地方。</p><p>下一個特性允許虛擬vxvlan接口在3層網絡上創建2層網絡(Virtual eXtensible Local Area Network (VXLAN))。這通常用於隧道虛擬網絡。</p><p>內核發送給網絡的消息可任意通過這個特性記錄下來(Network console logging support)。除非記錄網絡信息對你很重要時才啓用它。禁用這個特性會增強性能。</p><p>這個特性允許不同參數被改變(Dynamic reconfiguration of logging targets)。這些參數包括端口號、MAC地址、IP地址和其他一些設定。</p><p>如果用户空間程序希望使用TAP設備，那麼啓用這個特性可以允許這樣的活動(Universal TUN/TAP device driver support)。</p><p>這個驅動用於本地以太網隧道(Virtual ethernet pair device)。</p><p>&quot;Virtio network driver&quot;用於QEMU、Xen、KVM和其他虛擬機。</p><p>下一步，可以啓用&quot;ARCnet support&quot;。ARCnet是一種類似令牌環本地局域網絡(Local-Area-Network (LAN)協議。ARCnet代表&quot;Attached Resource Computer Network&quot;(附加資源計算器網絡)。</p><p>現在，我們進入到&quot;ATM drivers&quot;。ATM代表&quot;Asynchronous Transfer Mode&quot;(異步傳輸模式)。ATM用於電信。</p><p>Marevell以太網交換機芯片需要這個驅動(Marvell 88E6060 ethernet switch chip support)。同樣，這類交換機的芯片同樣需要依賴模型(Marvell 88E6085/6095/6095F/6131 ethernet switch chip support)和(Marvell 88E6123/6161/6165 ethernet switch chip support)。</p><p>現在，我們可以學習關於&quot;Ethernet driver support&quot;。</p><p>首先我們可以啓用/禁用&quot;3Com devices&quot;。接下來允許內核開發者選擇支持哪些3Com設備。</p><p>下一組選項是對於不同的&quot;Adaptec devices&quot;和接下來的&quot;Alteon devices&quot;。</p><p>這些只是特定設備/供應商驅動。通常地，這些驅動被作為模組加入。</p><p>在設置了這兩組選項後，接下來還有&quot;AMD devices&quot;和&quot;Atheros devices&quot;。</p><p>注意：請記住內核會運行在哪類硬件上。對於大量不同的設備，或許最好把它們作為模組加入</p><p>這裏有不同特定供貨商的設備驅動-&quot;Cadence devices&quot;、&quot;Broadcom devices&quot;、&quot;Brocade devices&quot;、&quot;Chelsio devices&quot;、&quot;Cisco devices&quot;、&quot;Digital Equipment devices&quot;。一些其他的特定設備/供應商驅動遵循它們。</p><p>接下來的驅動並不是特定設備/供應商的 &quot;SLIP (serial line) support&quot;。這個驅動支持SLIP和CSLIP。SLIP(Serial Line Internet Protocol)是一種用於調製解調器和串口的因特網驅動。PPP現在用來代替SLIP。CSLIP是壓縮的SLIP。</p><p>下面，&quot;CSLIP compressed headers&quot;可以啓用用來壓縮TCP/IP頭。CSLIP快於SLIP，但是想要啓用CSLIP，傳輸和接收的計算機都必須理解CSLIP。</p><p>當在惡劣的模擬線路上使用SLIP時，最好啓用&quot;Keepalive and linefill&quot;，這會幫助保持連接。</p><p>對於質量差的網絡或者7bit網絡中運行IP而言，最好啓用&quot;Six bit SLIP encapsulation&quot;。</p><p>現在我們可以進入流行的USB系統，但是這些是用於網絡的USB驅動。</p><p>第一個啓用/禁用的USB網絡設備是&quot;USB CATC NetMate-based Ethernet device support&quot;。這是用於10Mbps的USB以太網EL1210A芯片設備。USB設備將會扮演和成為一個以太網設備即使硬件是USB。</p><p>接下來，除了設備是KLSI KL5KUSB101B芯片組(USB KLSI KL5USB101-based ethernet device support)，其他與上面的驅動一樣。</p><p>Pegasus USB是USB轉以太網的適配器/轉換器(USB Pegasus/Pegasus-II based ethernet device support)。</p><p>接下來是另外一個USB轉以太網驅動(USB RTL8150 based ethernet device support)。</p><p>下一篇文章中，我們將繼續配置USB網絡系統。</p><hr>',56)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-14.4765/"},{default:r(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-14.4765/",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=t("譯者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:r(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const g=n(d,[["render",I]]);export{v as __pageData,g as default};
